from pathlib import Path
p=Path('src/main.jsx')
s=p.read_text()
start=s.find('function AdminFinance(')
end=s.find('function AdminInvites(', start)
if start<0 or end<0: raise SystemExit('AdminFinance/AdminInvites boundary not found')
fn=r'''function AdminFinance({p}){
 const month0=new Date();month0.setDate(1);const[month,setMonth]=useState(month0.toISOString().slice(0,10)),[people,setPeople]=useState([]),[dues,setDues]=useState([]),[charges,setCharges]=useState([]),[form,setForm]=useState({profile_id:'',description:'',amount:'',due_date:''}),[msg,setMsg]=useState(''),[busy,setBusy]=useState(false)
 const load=async()=>{const[{data:ps,error:e1},{data:ds,error:e2},{data:cs,error:e3}]=await Promise.all([supabase.from('profiles').select('id,name,email,role,is_active').order('name'),supabase.from('monthly_dues').select('*,profiles(name)').eq('reference_month',month),supabase.from('extra_charges').select('*,profiles(name)').order('due_date',{ascending:true})]);if(e1||e2||e3){setMsg((e1||e2||e3).message);return}setPeople(ps||[]);setDues(ds||[]);setCharges(cs||[])}
 useEffect(()=>{load()},[month])
 const setDue=async(profileId,status)=>{setBusy(true);const{error}=await supabase.rpc('admin_set_monthly_dues',{p_profile_id:profileId,p_reference_month:month,p_status:status});if(error)setMsg(error.message);else await load();setBusy(false)}
 const addCharge=async()=>{if(!form.description||!form.amount||!form.due_date)return;setBusy(true);const targets=form.profile_id==='__all__'?people.filter(x=>x.is_active).map(x=>x.id):[form.profile_id];for(const id of targets){const{error}=await supabase.rpc('create_extra_charge',{p_profile_id:id,p_description:form.description,p_amount:Number(form.amount),p_due_date:form.due_date,p_gira_id:null});if(error){setMsg(error.message);setBusy(false);return}}setForm({profile_id:'',description:'',amount:'',due_date:''});await load();setBusy(false)}
 const setCharge=async(id,status)=>{const{error}=await supabase.rpc('admin_set_extra_charge_status',{p_charge_id:id,p_status:status});if(error)setMsg(error.message);else await load()}
 const paid=dues.filter(x=>x.status==='paid').length;const unpaid=dues.filter(x=>x.status==='unpaid').length
 return <><div className="row between"><div><span className="eyebrow">FINANCEIRO</span><h2 style={{margin:'6px 0'}}>Controle da casa</h2><p className="muted small">Mensalidades e cobranças extras.</p></div><button className="btn" onClick={load}><RefreshCw size={15}/> Atualizar</button></div>{msg&&<div className="toast">{msg}</div>}<div className="field"><label>Mês de referência</label><input className="input" type="date" value={month} onChange={e=>setMonth(e.target.value.slice(0,7)+'-01')}/></div><div className="grid3"><div className="stat"><b>{paid}</b><span>Pagas</span></div><div className="stat"><b>{unpaid}</b><span>Não pagas</span></div><div className="stat"><b>{people.filter(x=>x.is_active).length}</b><span>Pessoas ativas</span></div></div><div className="card"><h3>Mensalidades</h3><div className="list">{people.filter(x=>x.is_active).map(person=>{const due=dues.find(d=>d.profile_id===person.id);const status=due?.status||'unpaid';return <div className="list-item row between" key={person.id}><div><b>{person.name}</b><div className="muted small">{person.email}</div></div><button className={'btn '+(status==='paid'?'primary':'')} disabled={busy} onClick={()=>setDue(person.id,status==='paid'?'unpaid':'paid')}>{status==='paid'?'Pago ✓':'Não pago'}</button></div>})}</div></div><div className="card"><h3>Adicionar cobrança extra</h3><div className="field"><label>Pessoa</label><select className="select" value={form.profile_id} onChange={e=>setForm({...form,profile_id:e.target.value})}><option value="">Escolha uma pessoa</option><option value="__all__">Todas as pessoas ativas</option>{people.filter(x=>x.is_active).map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></div><div className="field"><label>Descrição</label><input className="input" value={form.description} onChange={e=>setForm({...form,description:e.target.value})} placeholder="Ex.: contribuição, material, atividade…"/></div><div className="grid"><div className="field"><label>Valor</label><input className="input" type="number" min="0" step="0.01" value={form.amount} onChange={e=>setForm({...form,amount:e.target.value})}/></div><div className="field"><label>Vencimento</label><input className="input" type="date" value={form.due_date} onChange={e=>setForm({...form,due_date:e.target.value})}/></div></div><button className="btn primary" disabled={busy||!form.profile_id} onClick={addCharge}><Plus size={15}/> Criar cobrança</button></div><div className="card"><h3>Cobranças extras</h3><div className="list">{charges.map(c=><div className="list-item" key={c.id}><div className="row between"><div><b>{c.profiles?.name}</b><div>{c.description}</div><div className="muted small">{money(c.amount)} · {c.due_date?new Date(c.due_date+'T12:00:00').toLocaleDateString('pt-BR'):'Sem vencimento'}</div></div><button className={'btn '+(c.status==='paid'?'primary':'')} onClick={()=>setCharge(c.id,c.status==='paid'?'unpaid':'paid')}>{c.status==='paid'?'Pago ✓':'Não pago'}</button></div></div>)}{charges.length===0&&<div className="empty">Nenhuma cobrança extra cadastrada.</div>}</div></div></>}
'''
p.write_text(s[:start]+fn+'\n'+s[end:])
